'use client';
const require_card = require("./card.cjs");
const require_card_block = require("./card-block.cjs");
//#region src/components/card/index.ts
/**
* Card component to present content in a structured way.
*
* @example
* <Card>
*  <Card.Block>Header</Card.Block>
*  <Card.Block>Content</Card.Block>
*  <Card.Block>Footer</Card.Block>
* </Card>
*/
const CardComponent = Object.assign(require_card.Card, { Block: require_card_block.CardBlock });
CardComponent.Block.displayName = "Card.Block";
//#endregion
exports.Card = CardComponent;
exports.CardBlock = require_card_block.CardBlock;
